  CREATE PROCEDURE [bud].[jsRejectBudgetAllocationRequest]      @flowId INT = 2,      @company INT = 1,      @userId INT = 68,      @remarks NVARCHAR(MAX) = 'R',      @action NVARCHAR(20) = 'Reject'  AS  BEGIN      SET NOCOUNT ON;        DECLARE @Message NVARCHAR(4000)        BEGIN TRY          BEGIN TRANSACTION            DECLARE @templateId INT,                  @totalStages INT,                  @currentStage INT,                  @rejectionRequired INT,                  @rejectedCount INT,                  @existingStatus NVARCHAR(50) = 'None',                  @currentStageId INT,                  @userStage INT,                  @userStageId INT,                  @previousStage INT,                  @previousStageId INT,                  @currentStageActions INT,                  @newDescription NVARCHAR(MAX),                  @budgetAllocationRequestId INT,                  @docCompany INT            -- Get Budget Allocation Request flow details          SELECT               @templateId = bf.templateId,              @totalStages = bf.totalStage,              @currentStage = bf.currentStage,              @budgetAllocationRequestId = bf.budgetAllocationRequestId          FROM bud.jsFlow bf          WHERE bf.id = @flowId            IF @templateId IS NULL              THROW 50001, 'Budget Allocation Request workflow not found with the specified parameters', 1            -- Get company from BudgetAllocationRequest -> BudgetMonthlyAllocations -> Budgets          SELECT @docCompany = b.company          FROM bud.BudgetAllocationRequest bar          INNER JOIN bud.BudgetMonthlyAllocations bma ON bar.budgetAllocationId = bma.allocationId          INNER JOIN bud.Budgets b ON bma.budgetId = b.budgetId          WHERE bar.id = @budgetAllocationRequestId            -- Validate company          IF @docCompany != @company              THROW 50003, 'Access denied: Budget Allocation Request belongs to a different company', 1            -- Current and previous stage IDs          SELECT @currentStageId = stageId          FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @currentStage            SET @previousStage = @currentStage - 1            SELECT @previousStageId = stageId          FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @previousStage            -- User stage          SELECT TOP 1 @userStage = jst.priority, @userStageId = jst.stageId          FROM jsUserStage us          JOIN jsStageTemplate jst ON us.stageId = jst.stageId          WHERE us.userId = @userId            AND jst.templateId = @templateId          ORDER BY jst.priority            IF @userStage IS NULL              THROW 50002, 'User is not assigned to any stage in this Budget Allocation Request workflow', 1            -- Count actions in current stage          SELECT @currentStageActions = COUNT(*)          FROM bud.jsFlowStatus          WHERE flowId = @flowId            AND stageId = @currentStageId            -- Check existing status for this user          SELECT TOP 1 @existingStatus = status          FROM bud.jsFlowStatus          WHERE flowId = @flowId            AND stageId = @userStageId            AND userId = @userId          ORDER BY createdOn DESC            -- REJECT LOGIC          IF @action = 'Reject'          BEGIN              IF @existingStatus = 'R' AND @userStage = @currentStage                  THROW 50021, 'User has already rejected this Budget Allocation Request.', 1                IF NOT EXISTS (                  SELECT 1                  FROM jsStageTemplate                  WHERE templateId = @templateId                    AND (stageId = @currentStageId OR (@currentStageActions = 0 AND stageId = @previousStageId))                    AND EXISTS (SELECT 1 FROM jsUserStage WHERE stageId = jsStageTemplate.stageId AND userId = @userId)              )                  THROW 50006, 'User is not authorized to reject this Budget Allocation Request at the current stage.', 1                -- If previously approved, move back to user stage              IF @existingStatus = 'A' AND @userStage < @currentStage AND @currentStageActions = 0              BEGIN                  UPDATE bud.jsFlow                  SET currentStage = @userStage,                      currentStageId = @userStageId,                      updatedOn = SYSUTCDATETIME()                  WHERE id = @flowId                    SET @Message = 'Budget Allocation Request moved back to previous stage for rejection'              END                -- Insert or update rejection record              IF @existingStatus IS NULL OR @existingStatus = 'None'              BEGIN                  INSERT INTO bud.jsFlowStatus                      (flowId, status, stageId, templateId, userId, createdOn, description)                  VALUES                      (@flowId, 'R', @userStageId, @templateId, @userId, SYSUTCDATETIME(), @remarks)              END              ELSE              BEGIN                  UPDATE bud.jsFlowStatus                  SET status = 'R',                      description = @remarks,                      createdOn = SYSUTCDATETIME()                  WHERE flowId = @flowId                    AND stageId = @userStageId                    AND userId = @userId              END                -- Re-evaluate stage              SELECT @currentStage = currentStage              FROM bud.jsFlow              WHERE id = @flowId                SELECT @currentStageId = stageId              FROM jsStageTemplate              WHERE templateId = @templateId AND priority = @currentStage                -- Rejection counts              SELECT @rejectionRequired = rejection              FROM jsStage s              JOIN jsRejectionCount rc ON s.approvalId = rc.id              WHERE s.id = @currentStageId                SELECT @rejectedCount = COUNT(*)              FROM bud.jsFlowStatus              WHERE flowId = @flowId                AND stageId = @currentStageId                AND status = 'R'                IF @rejectedCount >= @rejectionRequired              BEGIN                  UPDATE bud.jsFlow                  SET status = 'R', updatedOn = SYSUTCDATETIME()                  WHERE id = @flowId                    SET @Message = 'Budget Allocation Request rejected successfully'              END              ELSE              BEGIN                  SET @Message = 'Not enough rejections to mark the Budget Allocation Request as rejected'              END          END          -- CANCEL LOGIC          ELSE IF @action = 'Cancel'          BEGIN              IF @existingStatus != 'R'                  THROW 50011, 'You cannot cancel a rejection you never made.', 1                IF @currentStageActions > 0 AND @userStage < @currentStage                  THROW 50007, 'Cannot cancel rejection because actions have already been taken in the current stage', 1                SELECT @newDescription = ISNULL(description, '')              FROM bud.jsFlowStatus              WHERE flowId = @flowId                AND stageId = @userStageId                AND userId = @userId                EXEC sp_executesql                   N'SELECT @Result = @Existing + '' | Cancelled: '' + @RemarkText',                  N'@Existing NVARCHAR(MAX), @RemarkText NVARCHAR(MAX), @Result NVARCHAR(MAX) OUTPUT',                  @newDescription, @remarks, @newDescription OUTPUT                UPDATE bud.jsFlowStatus              SET status = 'Cancelled',                  description = @newDescription,                  createdOn = SYSUTCDATETIME()              WHERE flowId = @flowId                AND stageId = @userStageId                AND userId = @userId                AND status = 'R'                IF @userStage < @currentStage              BEGIN                  UPDATE bud.jsFlow                  SET currentStage = @userStage,                      currentStageId = @userStageId,                      status = 'P',                      updatedOn = SYSUTCDATETIME()                  WHERE id = @flowId                    SET @Message = 'Rejection cancelled and Budget Allocation Request returned to previous stage'              END              ELSE              BEGIN                  SET @Message = 'Rejection cancelled in current stage'              END          END          ELSE              THROW 50009, 'Invalid action specified. Use "Reject" or "Cancel"', 1            COMMIT TRANSACTION            SELECT               @Message AS ResultMessage,               @budgetAllocationRequestId AS BudgetAllocationRequestId,               @docCompany AS CompanyId,              @flowId AS FlowId        END TRY      BEGIN CATCH          IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION            DECLARE @ErrorMessage NVARCHAR(4000),                  @ErrorSeverity INT,                  @ErrorState INT            SELECT @ErrorMessage = ERROR_MESSAGE(),                 @ErrorSeverity = ERROR_SEVERITY(),                 @ErrorState = ERROR_STATE()            RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState)      END CATCH  END
